const markInvoiceComplaintSellerResponded = `-- name: MarkInvoiceComplaintSellerResponded :execrows
UPDATE invoice_complaints
SET status = 'SELLER_RESPONDED',
    buyer_review_due_at = $1,
    first_responded_at = COALESCE(first_responded_at, $2),
    updated_at = $2,
    version = version + 1
WHERE invoice_complaints.id = $3
  AND invoice_complaints.status IN ('OPEN', 'OVERDUE')
  AND invoice_complaints.version = $4
  AND invoice_complaints.issuer_id = (
        SELECT i.id FROM invoice_issuers i
         WHERE i.issuer_type = 'SELLER' AND i.issuer_ref_id = $5::bigint)
`

type MarkInvoiceComplaintSellerRespondedParams struct {
	BuyerReviewDueAt *time.Time         `db:"buyer_review_due_at" json:"buyer_review_due_at"`
	Now              pgtype.Timestamptz `db:"now" json:"now"`
	ID               int64              `db:"id" json:"id"`
	ExpectedVersion  int64              `db:"expected_version" json:"expected_version"`
	StoreID          int64              `db:"store_id" json:"store_id"`
}

// K02 OPEN／OVERDUE → SELLER_RESPONDED（賣家回覆；OVERDUE 是「逾期後仍回覆」那條）。
// 回覆內容採**追加事件**寫 invoice_complaint_events，**不覆蓋前次**——本句不碰任何內容欄。
// buyer_review_due_at = now + 72h 由呼叫端傳入；它是 K06（逾期視為接受 → RESOLVED）
//
//	唯一的觸發依據，也是 idx_invcomp_buyer_review_due 的鍵。少寫 ⇒ 該案永遠不會自動結案，
//	而且沒有任何錯誤：那一列只是從 K06 的候選集合裡消失。
//
// first_responded_at 用 COALESCE 保留第一次：它是事實時間戳，不因賣家二次回覆而後移。
// 🔴 `version = expected_version` 與擁有者述詞都在**這一句**（2026-08-30 補）：
//
//	端點 36 的 expectedVersion 是 §6.1 共通形狀的必填欄，而「必填」只有寫進述詞才是保證
//	——少了它，兩個分頁同時送出時各自讀到舊版本、各自通過，第二筆只是碰巧被 status
//	述詞擋掉（那是巧合不是設計）。擁有者述詞同理：先 SELECT 再 UPDATE 的寫法在兩句之間
//	有窗口，而且把 Tier A 的保證搬到了呼叫端的 if 上（§8.1.4(b)）。
func (q *Queries) MarkInvoiceComplaintSellerResponded(ctx context.Context, arg MarkInvoiceComplaintSellerRespondedParams) (int64, error) {
	result, err := q.db.Exec(ctx, markInvoiceComplaintSellerResponded,
		arg.BuyerReviewDueAt,
		arg.Now,
		arg.ID,
		arg.ExpectedVersion,
		arg.StoreID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

